'use strict';

/**
* Compute the Cartesian square for a single-precision complex floating-point strided array.
*
* @module @stdlib/blas/ext/base/ccartesian-square
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var ccartesianSquare = require( '@stdlib/blas/ext/base/ccartesian-square' );
*
* var x = new Complex64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var out = new Complex64Array( 8 );
*
* ccartesianSquare( 'row-major', x.length, x, 1, out, 2 );
* // out => <Complex64Array>[ 1.0, 2.0, 1.0, 2.0, 1.0, 2.0, 3.0, 4.0, 3.0, 4.0, 1.0, 2.0, 3.0, 4.0, 3.0, 4.0 ]
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var ccartesianSquare = require( '@stdlib/blas/ext/base/ccartesian-square' );
*
* var x = new Complex64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var out = new Complex64Array( 8 );
*
* ccartesianSquare.ndarray( x.length, x, 1, 0, out, 2, 1, 0 );
* // out => <Complex64Array>[ 1.0, 2.0, 1.0, 2.0, 1.0, 2.0, 3.0, 4.0, 3.0, 4.0, 1.0, 2.0, 3.0, 4.0, 3.0, 4.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var ccartesianSquare;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	ccartesianSquare = main;
} else {
	ccartesianSquare = tmp;
}


// EXPORTS //

module.exports = ccartesianSquare;

// exports: { "ndarray": "ccartesianSquare.ndarray" }
